            <h3>发布新帖</h3>
            <button class="modal-close" @click="showPostModal = false">&times;</button>
          </div>
          <form class="post-form" @submit.prevent="submitPost">
            <!-- 标题 -->
            <div class="form-group">
              <label for="post-title">标题 <span class="required">*</span></label>
              <input
                id="post-title"
                v-model="postForm.title"
                type="text"
                placeholder="请输入帖子标题"
                maxlength="100"
                :class="{ error: formErrors.title }"
              />
              <span v-if="formErrors.title" class="error-text">{{ formErrors.title }}</span>
            </div>
            <!-- 分类 -->
            <div class="form-group">
              <label for="post-category">分类 <span class="required">*</span></label>
              <select
                id="post-category"
                v-model="postForm.category"
                :class="{ error: formErrors.category }"
              >
                <option value="">请选择分类</option>
                <option v-for="cat in postCategories" :key="cat" :value="cat">{{ cat }}</option>
              </select>
              <span v-if="formErrors.category" class="error-text">{{ formErrors.category }}</span>
            </div>
            <!-- 内容 -->
            <div class="form-group">
              <label for="post-content">内容 <span class="required">*</span></label>
              <textarea
                id="post-content"
                v-model="postForm.content"
                placeholder="分享你的非遗文化心得..."
                rows="6"
                maxlength="2000"
                :class="{ error: formErrors.content }"
              ></textarea>
              <div class="textarea-footer">
                <span v-if="formErrors.content" class="error-text">{{ formErrors.content }}</span>
                <span class="char-count">{{ postForm.content.length }}/2000</span>
              </div>
            </div>
            <!-- 提交按钮 -->
            <div class="form-actions">
              <button type="button" class="btn-cancel" @click="showPostModal = false">
                取消
              </button>
              <button type="submit" class="btn-submit" :disabled="submitting">
                {{ submitting ? '发布中...' : '发布' }}
              </button>
            </div>
          </form>
        </div>
