<script setup>
/**
 * CommunityView.vue - 交流社区页面
 *
 * 功能说明：
 * - 展示社区帖子列表，支持分类和排序
 * - 右侧边栏展示社区统计和热门话题
 * - 发帖功能（模拟），带表单验证
 * - 完整的分页、加载状态和空状态
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import { useRouter } from 'vue-router'
import PostCard from '@/components/PostCard.vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import EmptyState from '@/components/EmptyState.vue'

// 获取 Vuex store 和 router 实例
const store = useStore()
const router = useRouter()

// ==================== 响应式状态 ====================

/** 当前选中的分类 */
const currentCategory = ref('all')
/** 当前排序方式 */
const sortBy = ref('latest')
/** 当前页码 */
const currentPage = ref(1)
/** 每页帖子数量 */
const pageSize = ref(10)
/** 是否显示发帖弹窗 */
const showPostModal = ref(false)
/** 是否移动端 */
const isMobile = ref(window.innerWidth < 768)
/** 是否正在提交 */
const submitting = ref(false)

/** 发帖表单数据 */
const postForm = ref({
  title: '',
  category: '',
  content: ''
})

/** 表单错误信息 */
const formErrors = ref({
  title: '',
  category: '',
  content: ''
})

// ==================== 分类和排序配置 ====================

/** 帖子分类选项 */
const categories = [
  { label: '全部', value: 'all' },
  { label: '学习心得', value: '学习心得' },
  { label: '技艺交流', value: '技艺交流' },
  { label: '活动分享', value: '活动分享' },
  { label: '求助问答', value: '求助问答' },
  { label: '作品展示', value: '作品展示' }
]

/** 发帖时可选择的分类 */
const postCategories = ['学习心得', '技艺交流', '活动分享', '求助问答', '作品展示']

/** 排序选项 */
const sortOptions = [
  { label: '最新', value: 'latest' },
  { label: '最热', value: 'hottest' },
  { label: '精华', value: 'essential' }
]

// ==================== 计算属性 ====================

/** 从 Vuex store 获取加载状态 */
const loading = computed(() => store.state.loading)

/** 从 Vuex store 获取帖子列表 */
const posts = computed(() => store.state.posts || [])

/** 根据分类筛选后的帖子 */
const filteredPosts = computed(() => {
  if (currentCategory.value === 'all') return posts.value
  return posts.value.filter(p => p.category === currentCategory.value)
})

/** 筛选并排序后的帖子 */
const sortedPosts = computed(() => {
  const list = [...filteredPosts.value]
  switch (sortBy.value) {
    case 'hottest':
      // 按浏览量+点赞数排序
      return list.sort((a, b) => {
        const hotA = (a.views || 0) + (a.likes || 0) * 2
        const hotB = (b.views || 0) + (b.likes || 0) * 2
        return hotB - hotA
      })
    case 'essential':
      // 精华帖：isHot=true 的排前面
      return list.sort((a, b) => (b.isHot ? 1 : 0) - (a.isHot ? 1 : 0))
    default:
      // 最新：按时间倒序
      return list.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
  }
})

/** 分页后的帖子 */
const paginatedPosts = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  const end = start + pageSize.value
  return sortedPosts.value.slice(start, end)
})

/** 总页数 */
const totalPages = computed(() => Math.ceil(sortedPosts.value.length / pageSize.value))

/** 可见页码 */
const visiblePages = computed(() => {
  const pages = []
  const max = totalPages.value
  const current = currentPage.value
  let start = Math.max(1, current - 2)
  let end = Math.min(max, current + 2)
  if (end - start < 4) {
    if (start === 1) end = Math.min(max, start + 4)
    else if (end === max) start = Math.max(1, end - 4)
  }
  for (let i = start; i <= end; i++) pages.push(i)
  return pages
})

/** 今日新帖数量（模拟） */
const todayPosts = computed(() => {
  const today = new Date().toDateString()
  return posts.value.filter(p => new Date(p.createdAt).toDateString() === today).length || 12
})

/** 总帖子数量 */
const totalPosts = computed(() => posts.value.length || 156)

/** 在线人数（模拟） */
const onlineUsers = ref(28)

/** 热门话题（按回复数排序的前8篇） */
const hotTopics = computed(() => {
  return [...posts.value]
    .sort((a, b) => (b.comments || 0) - (a.comments || 0))
    .slice(0, 8)
})

// ==================== 方法 ====================

/**
 * 设置当前分类并重置页码
 * @param {string} value - 分类值
 */
const setCategory = (value) => {
  currentCategory.value = value
  currentPage.value = 1
}

/**
 * 跳转到帖子详情
 * @param {string} id - 帖子ID
 */
const goToDetail = (id) => {
  router.push(`/community/${id}`)
}

/**
 * 验证发帖表单
 * @returns {boolean} 验证是否通过
 */
const validateForm = () => {
  const errors = {}
  if (!postForm.value.title.trim()) {
    errors.title = '请输入帖子标题'
  } else if (postForm.value.title.trim().length < 4) {
    errors.title = '标题至少需要4个字符'
  }
  if (!postForm.value.category) {
    errors.category = '请选择分类'
  }
  if (!postForm.value.content.trim()) {
    errors.content = '请输入帖子内容'
  } else if (postForm.value.content.trim().length < 10) {
    errors.content = '内容至少需要10个字符'
  }
  formErrors.value = errors
  return Object.keys(errors).length === 0
}

/**
 * 提交发帖表单
 */
const submitPost = async () => {
  if (!validateForm()) return
  submitting.value = true
  try {
    await store.dispatch('createPost', {
      title: postForm.value.title.trim(),
      category: postForm.value.category,
      content: postForm.value.content.trim()
    })
    // 重置表单并关闭弹窗
    postForm.value = { title: '', category: '', content: '' }
    formErrors.value = {}
    showPostModal.value = false
    // 刷新帖子列表
    await store.dispatch('fetchPosts')
  } catch (err) {
    console.error('发帖失败:', err)
  } finally {
    submitting.value = false
  }
}

/**
 * 处理窗口大小变化
 */
const handleResize = () => {
  isMobile.value = window.innerWidth < 768
}

// ==================== 生命周期 ====================

onMounted(async () => {
  window.addEventListener('resize', handleResize)
  try {
    await store.dispatch('fetchPosts')
  } catch (err) {
    console.error('获取帖子列表失败:', err)
  }
})
</script>

